import test from "node:test";
import assert from "node:assert/strict";
import {inspectArtifactFormat} from "../src/main/services/artifact-format.ts";

// Independently encoded 1 x 1 transparent PNG, not generated by the parser.
const pixel = Buffer.from("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAAC0lEQVR42mNgAAIAAAUAAen63NgAAAAASUVORK5CYII=", "base64");

test("PNG fingerprints require intact chunks rather than an extension or magic prefix", () => {
  assert.deepEqual(inspectArtifactFormat(pixel), {detectedFormat: "png", width: 1, height: 1});
  for (const bytes of [Buffer.from("A chart was exported successfully."), pixel.subarray(0, 12), pixel.subarray(0, pixel.length - 1), Buffer.concat([pixel, Buffer.from("tail")])]) {
    assert.deepEqual(inspectArtifactFormat(bytes), {});
  }
  const corrupt = Buffer.from(pixel); corrupt[44] ^= 1;
  assert.deepEqual(inspectArtifactFormat(corrupt), {}, "corrupt image content cannot retain a valid fingerprint format");
});

test("PDF structural detection requires an actual bounded xref and final EOF", () => {
  const prefix = "%PDF-1.4\n1 0 obj\n<< /Type /Catalog >>\nendobj\n";
  const pdf = Buffer.from(`${prefix}xref\n0 2\n0000000000 65535 f \n0000000009 00000 n \ntrailer\n<< /Size 2 /Root 1 0 R >>\nstartxref\n${Buffer.byteLength(prefix)}\n%%EOF\n`);
  assert.deepEqual(inspectArtifactFormat(pdf), {detectedFormat: "pdf"});
  assert.deepEqual(inspectArtifactFormat(Buffer.from("%PDF-1.4\nJust text pretending to be a PDF\n%%EOF")), {});
  assert.deepEqual(inspectArtifactFormat(Buffer.from(pdf.toString().replace(/startxref\n\d+/, "startxref\n99999999"))), {});
  assert.deepEqual(inspectArtifactFormat(pdf.subarray(0, pdf.length - 7)), {});
});
